import pandas as pd


def run(inputs: dict) -> dict:
    dim_account = inputs["dim_account"].copy()
    stg_account = inputs["stg_account"].copy()

    # Build initial per-account version lists from existing dimension state.
    versions = {}
    for _, row in dim_account.iterrows():
        acc = row["account_id"]
        versions.setdefault(acc, []).append({
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
            "is_current": row["is_current"],
        })

    # Stable sort preserves original relative order for ties on
    # (account_id, update_date), matching cursor semantics.
    stg_sorted = stg_account.sort_values(
        ["account_id", "update_date"], kind="mergesort"
    )

    def plan_eq(a, b):
        a_null = pd.isna(a)
        b_null = pd.isna(b)
        if a_null and b_null:
            return True
        if a_null != b_null:
            return False
        return a == b

    for _, s in stg_sorted.iterrows():
        acc = s["account_id"]
        plan = s["plan"]
        upd = s["update_date"]

        if acc not in versions or len(versions[acc]) == 0:
            versions.setdefault(acc, []).append({
                "plan": plan,
                "eff_start_date": upd,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
            continue

        vs = versions[acc]

        # Find the version covering upd: start <= upd < end (end NULL = open).
        v = None
        for ver in vs:
            start = ver["eff_start_date"]
            end = ver["eff_end_date"]
            if start <= upd and (pd.isna(end) or upd < end):
                v = ver
                break

        if v is None:
            # upd predates the account's earliest version.
            f = min(vs, key=lambda x: x["eff_start_date"])
            vs.append({
                "plan": plan,
                "eff_start_date": upd,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        elif plan_eq(v["plan"], plan):
            pass
        elif upd == v["eff_start_date"]:
            v["plan"] = plan
        else:
            new_ver = {
                "plan": plan,
                "eff_start_date": upd,
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            }
            vs.append(new_ver)
            v["eff_end_date"] = upd
            v["is_current"] = 0

    rows = []
    for acc, vs in versions.items():
        for ver in vs:
            rows.append({
                "account_id": acc,
                "plan": ver["plan"],
                "eff_start_date": ver["eff_start_date"],
                "eff_end_date": ver["eff_end_date"],
                "is_current": ver["is_current"],
            })

    out = pd.DataFrame(
        rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out.empty:
        out["account_id"] = out["account_id"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
        out["is_current"] = out["is_current"].astype("int64")

    return {"dim_account_out": out}
